-- Yahya's list (added for him). Pins/hotel/travel/Maps link are ✨ generated; skips any place that already exists by name.
insert into public.places (kind, name, description, visit_minutes, category, lat, lng, nearest_hotels, travel_minutes, travel_text, maps_url, halal, taste, created_by, auto_fields, auto_sources)
select v.* from (values
('activity','Liberty Walk Tokyo (LBWK)','Cat Street, Harajuku. Car-culture streetwear: graphic tees, racing/varsity jackets, LBWK x New Era backpack, Mini GT 1:64 diecasts and 1:43 scale models.',60,'shopping',35.6658625,139.7051482,array['toranomon'],23,'~23 min by train/car (est., 4.0 km)','https://www.google.com/maps/search/Liberty%20Walk%20Tokyo/@35.665863,139.705148,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Kiddy Land Harajuku','Omotesando. Toy & character mecca: Sanrio (Kuromi, Cinnamoroll), plushies for Yusrah, squishies and character socks.',60,'shopping',35.6677204,139.706537,array['toranomon'],23,'~23 min by train/car (est., 3.9 km)','https://www.google.com/maps/search/Kiddy%20Land%20Harajuku/@35.667720,139.706537,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Cat Café MOCHA Harajuku','Relaxing break to sit, pet the cats and grab a drink.',45,'fun',35.6700156,139.703029,array['toranomon'],24,'~24 min by train/car (est., 4.2 km)','https://www.google.com/maps/search/Cat%20Caf%C3%A9%20MOCHA%20Harajuku/@35.670016,139.703029,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Unrevised Studios & Ura-Harajuku streetwear','Back streets of Harajuku: independent streetwear brands, graphic tees, hoodies and Japanese urban apparel.',40,'shopping',35.6704333,139.7107597,array['toranomon'],22,'~22 min by train/car (est., 3.5 km)','https://www.google.com/maps/search/Unrevised%20Studios%20%26%20Ura-Harajuku%20streetwear/@35.670433,139.710760,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Tokyo Camii Mosque & 100% Halal Market','Yoyogi-Uehara (1 stop from Shibuya/Shinjuku). Tokyo''s main mosque & Islamic cultural centre with prayer space, plus a 100% halal supermarket: Japanese snacks, bento, sweets and Turkish pastries.',60,'culture',35.6681705,139.6765497,array['toranomon'],31,'~31 min by train/car (est., 6.6 km)','https://www.google.com/maps/search/Tokyo%20Camii%20Mosque%20%26%20100%25%20Halal%20Market/@35.668171,139.676550,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Ameyoko Halal Street Market & Underground Bazaar','Ueno/Okachimachi, Tokyo''s biggest halal street market. Open-air halal kiosks (chicken/beef kebabs, grilled skewers, fruit skewers) plus Ameyoko Center Building B1: Asian/Middle Eastern halal food market and butchers.',90,'food',35.7100241,139.7745414,array['toranomon'],27,'~27 min by train/car (est., 5.3 km)','https://www.google.com/maps/search/Ameyoko%20Halal%20Street%20Market%20%26%20Underground%20Bazaar/@35.710024,139.774541,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Niki no Kashi (snack warehouse)','Ameyoko. Bulk candy and Japanese snack haul.',30,'food',35.7083752,139.7744702,array['toranomon'],27,'~27 min by train/car (est., 5.1 km)','https://www.google.com/maps/search/Niki%20no%20Kashi/@35.708375,139.774470,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Tokyodo International Karate Shop','1-10-9 Yanagibashi, Taito (Asakusabashi). High-grade karate gi for Yusrah, sparring gear, and custom kanji-embroidered black belts.',50,'shopping',35.6964887,139.7883157,array['toranomon'],26,'~26 min by train/car (est., 4.8 km)','https://www.google.com/maps/search/Tokyodo%20International%20Karate%20Shop/@35.696489,139.788316,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Nissan Crossing','Ginza Place, Ginza 4-chome crossing. Concept cars & Formula E racers on display, plus GT-R logo latte art at the 2nd-floor café.',40,'fun',35.6709378,139.7650596,array['toranomon'],16,'~16 min by train/car (est., 1.5 km)','https://www.google.com/maps/search/Nissan%20Crossing/@35.670938,139.765060,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Kama-Asa Shoten (Kappabashi knives)','2-24-1 Matsugaya, Kappabashi Kitchen Street. Hand-forged Damascus chef knife with your name engraved in kanji on-site.',50,'shopping',35.7138596,139.788644,array['toranomon'],30,'~30 min by train/car (est., 6.3 km)','https://www.google.com/maps/search/Kama-Asa%20Shoten/@35.713860,139.788644,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Yodobashi Camera Multimedia Akiba','Linked to JR Akihabara. 9 floors of tech: audio, mechanical keyboards, gaming setups, cameras; tax-free shopping.',105,'shopping',35.6987843,139.7747251,array['toranomon'],24,'~24 min by train/car (est., 4.2 km)','https://www.google.com/maps/search/Yodobashi%20Camera%20Multimedia%20Akiba/@35.698784,139.774725,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','ADA LAB Tokyo (Daimaru, 10F)','Daimaru Tokyo Station 10th floor. ADA Green Brighty water additives, AP Series fish food and ADA LAB merch.',30,'shopping',35.6812599,139.7688241,array['toranomon'],19,'~19 min by train/car (est., 2.3 km)','https://www.google.com/maps/search/ADA%20LAB%20Tokyo/@35.681260,139.768824,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Tokyo Okashi Land','Tokyo Station First Avenue B1. Fresh, warm Calbee chocolate-drizzled potato chips fried on-site.',30,'food',35.680889,139.7681659,array['toranomon'],18,'~18 min by train/car (est., 2.3 km)','https://www.google.com/maps/search/Tokyo%20Okashi%20Land/@35.680889,139.768166,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Tokyo Character Street','Tokyo Station First Avenue B1. Pokémon Center, Studio Ghibli, Kirby and Sanrio shops.',60,'shopping',35.6823859,139.7687416,array['toranomon'],19,'~19 min by train/car (est., 2.4 km)','https://www.google.com/maps/search/Tokyo%20Character%20Street/@35.682386,139.768742,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Shimokitazawa vintage & streetwear','Pedestrian alleys packed with vintage workwear, rare graphic tees, Japanese denim and streetwear.',105,'shopping',35.6616779,139.6663345,array['jw_tokyo'],33,'~33 min by train/car (est., 7.3 km)','https://www.google.com/maps/search/Shimokitazawa%20vintage%20%26%20streetwear/@35.661678,139.666335,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','MEGA Don Quijote Shibuya','Udagawacho flagship. Pharmacy/personal-care stash (Rohto Z! eye drops, stain pens, liquid bandages, cooling sheets, nail clippers…) plus plushies and character socks.',105,'shopping',35.6604474,139.6978406,array['jw_tokyo'],25,'~25 min by train/car (est., 4.7 km)','https://www.google.com/maps/search/MEGA%20Don%20Quijote%20Shibuya/@35.660447,139.697841,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Loft Ginza','3-min walk from Nissan Crossing. Uni Kuru Toga auto-rotating pencils and Japanese stationery.',45,'shopping',35.674097,139.7662311,array['toranomon'],17,'~17 min by train/car (est., 1.7 km)','https://www.google.com/maps/search/Loft%20Ginza/@35.674097,139.766231,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('activity','Karen luggage (Ginza)','Backup stop if an extra 71 cm hard-shell suitcase is needed for the haul.',25,'shopping',35.6743469,139.7670332,array['toranomon'],17,'~17 min by train/car (est., 1.8 km)','https://www.google.com/maps/search/Karen%20luggage/@35.674347,139.767033,17z',null,null,'53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)'),
('restaurant','Halal Yakiniku PANGA (A5 Wagyu)','Okachimachi/Ueno. 100% halal-certified A5 Japanese wagyu BBQ dinner (Gyu Sakura is the alternative).',90,null,35.7069531,139.7746303,array['toranomon'],26,'~26 min by train/car (est., 5.0 km)','https://www.google.com/maps/search/Halal%20Yakiniku%20PANGA/@35.706953,139.774630,17z','Halal certified','savory','53f179da-b92e-4fbe-8d53-d2ffde211f52'::uuid,array['pin','nearest_hotels','travel','maps_url']::text[],'https://nominatim.openstreetmap.org (OpenStreetMap search)')
) as v(kind, name, description, visit_minutes, category, lat, lng, nearest_hotels, travel_minutes, travel_text, maps_url, halal, taste, created_by, auto_fields, auto_sources)
where not exists (select 1 from public.places p where lower(p.name) = lower(v.name));
